using Godot;
using System;
using System.Collections.Generic;
using System.Text.RegularExpressions;
using Settings=Godot.Collections.Dictionary;
public partial class BasicActorOperations
{
    private readonly ActorTextSettingsOperations _text=new();private readonly ActorShaderTimeOperations _shaderTime=new();private readonly FogActorOperations _fog=new();private readonly GrowthActorOperations _growth=new();
    public void evaluate(Node3D owner,double time,Settings values)
    {
        var content=Content(owner);if(content==null)return;switch(Actor(owner).Get("type_id").AsString()){case "basic_shape":update_shape(owner,Get(values,"shape",0).AsInt32());apply_shape_properties((PrimitiveMesh)((MeshInstance3D)content).Mesh,values);apply_material_reference(owner,Get(values,"material"),null,false);break;case "basic_mesh":update_model(owner,Get(values,"mesh_path",""));apply_material_reference(owner,Get(values,"material"),null,true);_growth.apply(owner,values);break;case "text_3d":var label=(Label3D)content;label.Text=values["text"].AsString();var settings=_text.values(Get(values,"text_settings"));label.Font=_text.font(settings);label.FontSize=Math.Max(1,Get(settings,"font_size",Get(values,"font_size",48)).AsInt32());label.Modulate=Get(settings,"color",Get(values,"color",Colors.White)).AsColor();label.OutlineSize=Math.Max(0,Get(settings,"outline_size",0).AsInt32());label.OutlineModulate=Get(settings,"outline_color",Colors.Black).AsColor();var shadow=owner.Get("text_shadow").As<Label3D>();shadow.Visible=Get(settings,"shadow",false).AsBool();shadow.Text=label.Text;shadow.Font=label.Font;shadow.FontSize=label.FontSize;shadow.OutlineSize=0;shadow.Modulate=Get(settings,"shadow_color",new Color(0,0,0,.65f)).AsColor();var offset=Get(settings,"shadow_offset",new Vector2(2,2)).AsVector2();shadow.Position=new Vector3(offset.X*label.PixelSize,-offset.Y*label.PixelSize,-.001f);break;case "light_3d":apply_light(owner,values);break;case "directional_light":apply_directional_light(owner,values);break;case "camera_3d":((Camera3D)content).Fov=values["fov"].AsSingle();apply_camera_shader(owner,Get(values,"material"));break;case "image_3d":var image=Get(values,"image_path","");owner.Set("loaded_image_path",resource_identity(image));apply_material_reference(owner,Get(values,"material"),texture_for_value(owner,image),false);break;case "world_environment":apply_environment(owner,Get(values,"environment"));break;case "decal_3d":apply_decal(owner,values);break;case "particles_3d":apply_particles(owner,values);break;case "fog_volume":case "global_fog":apply_fog(owner,values);break;case "reflection_probe":apply_reflection_probe(owner,values);break;}_lighting.apply_geometry(owner,values);
    }
    private Resource? Resolve(Node3D owner,Variant value)
    {
        if(value.VariantType!=Variant.Type.Object||value.AsGodotObject() is not Resource reference||!ActorDataOperations.ScriptIs(reference,"res://scripts/actors/core/actor_object_reference.gd"))return null;var resource=reference.Get("source").AsInt32()==1?load_object_resource(reference.Get("asset_id").AsString()):reference.Get("embedded").As<Resource>();return resource!=null&&resource.Get("type_id").AsString()==reference.Get("object_type").AsString()?resource:null;
    }
    public Shader? shader_from_value(Node3D owner,Variant value){if(value.VariantType==Variant.Type.Object&&value.AsGodotObject() is Shader shader)return shader;if(value.VariantType==Variant.Type.String&&value.AsString().Length>0)return ResourceLoader.Load(godot_resource_path(value.AsString()),"",ResourceLoader.CacheMode.Ignore) as Shader;return null;}
    public string shader_source_key(Node3D owner,Variant value){if(value.VariantType==Variant.Type.Object&&value.AsGodotObject() is Shader shader)return shader.GetInstanceId()+":"+GD.Hash(shader.Code);if(value.VariantType==Variant.Type.String&&value.AsString().Length>0){string path=godot_resource_path(value.AsString());return Godot.FileAccess.FileExists(path)?path+":"+Godot.FileAccess.GetSha256(path):"missing:"+path;}return "empty";}
    public ShaderMaterial runtime_shader_material(Shader? source,string kind,bool screenInput)
    {
        var result=new ShaderMaterial();if(source==null||!Regex.IsMatch(source.Code,@"^\s*shader_type\s+"+kind+@"\s*;",RegexOptions.Multiline))return result;string code=source.Code;if(screenInput){string name="kiwi_camera_screen";while(code.Contains(name,StringComparison.Ordinal))name+="_";code=Regex.Replace(code,@"\bTEXTURE_PIXEL_SIZE\b","SCREEN_PIXEL_SIZE");code=Regex.Replace(code,@"\bTEXTURE\b",name);var declaration=Regex.Match(code,@"shader_type\s+canvas_item\s*;");if(declaration.Success)code=code.Insert(declaration.Index+declaration.Length,$"\nuniform sampler2D {name} : hint_screen_texture, filter_linear;\n");var fragment=Regex.Match(code,@"\bvoid\s+fragment\s*\(\s*\)\s*\{");code=fragment.Success?code.Insert(fragment.Index+fragment.Length,$"\nCOLOR = texture({name}, SCREEN_UV);\n"):code+$"\nvoid fragment() {{ COLOR = texture({name}, SCREEN_UV); }}\n";}var timed=_shaderTime.prepare(code);result.Shader=new Shader{Code=timed["code"].AsString()};result.SetMeta("kiwi_time_uniform",timed["uniform"]);return result;
    }
    public void apply_shader_uniforms(Node3D owner,ShaderMaterial? target,Resource data){if(target?.Shader==null)return;var uniforms=data.Get("values").AsGodotDictionary().GetValueOrDefault("uniforms",new Settings()).AsGodotDictionary();foreach(var item in target.Shader.GetShaderUniformList()){var info=item.AsGodotDictionary();string name=info.GetValueOrDefault("name","").AsString();if(name.Length==0||!uniforms.TryGetValue(new StringName(name),out var value))continue;if(info.GetValueOrDefault("type",0).AsInt32()==(int)Variant.Type.Object){var texture=texture_for_value(owner,value);value=texture!=null?Variant.From(texture):default;}target.SetShaderParameter(name,value);}}
    public void apply_camera_shader(Node3D owner,Variant value){var data=Resolve(owner,value);var overlay=owner.Get("camera_overlay").As<ColorRect>();if(data==null||data.Get("type_id").AsString()!="canvas_shader_material"){owner.Set("camera_shader_material",default(Variant));owner.Set("camera_shader_key","");overlay.Material=null;update_camera_overlay(owner);return;}var source=data.Get("values").AsGodotDictionary().GetValueOrDefault("shader_path","");string key=shader_source_key(owner,source);var material=owner.Get("camera_shader_material").As<ShaderMaterial>();if(material==null||key!=owner.Get("camera_shader_key").AsString()){owner.Set("camera_shader_key",key);material=runtime_shader_material(shader_from_value(owner,source),"canvas_item",true);owner.Set("camera_shader_material",material);}overlay.Material=material.Shader!=null?material:null;apply_shader_uniforms(owner,material,data);update_camera_overlay(owner);}
    public void apply_fog(Node3D owner,Settings values){var fog=(FogVolume)Content(owner)!;fog.Shape=(RenderingServer.FogVolumeShape)Get(values,"shape",3).AsInt32();fog.Size=Get(values,"volume_size",new Vector3(4,2,4)).AsVector3();var data=Resolve(owner,Get(values,"material"));var fallback=owner.Get("fog_material").As<FogMaterial>();if(data!=null&&data.Get("type_id").AsString()=="fog_shader_material"){var source=data.Get("values").AsGodotDictionary().GetValueOrDefault("shader_path","");string key=shader_source_key(owner,source);var material=owner.Get("fog_shader_material").As<ShaderMaterial>();if(material==null||key!=owner.Get("fog_shader_key").AsString()){owner.Set("fog_shader_key",key);material=runtime_shader_material(shader_from_value(owner,source),"fog",false);owner.Set("fog_shader_material",material);}fog.Material=material.Shader!=null?material:fallback;apply_shader_uniforms(owner,material,data);}else{fog.Material=fallback;owner.Set("fog_shader_material",default(Variant));owner.Set("fog_shader_key","");}if(fallback!=null){fallback.Density=Get(values,"density",1.0).AsSingle();fallback.Albedo=Get(values,"albedo",Colors.White).AsColor();fallback.Emission=Get(values,"emission",Colors.Black).AsColor()*Get(values,"emission_energy",1.0).AsSingle();fallback.EdgeFade=Get(values,"edge_fade",.1).AsSingle();}_fog.apply(owner,values);}
}
